  5189  static int
  5190  md_start_new_block(MD_CTX* ctx, const MD_LINE_ANALYSIS* line)
  5191  {
  5192      MD_BLOCK* block;
  5193
  5194      MD_ASSERT(ctx->current_block == NULL);
  5195
  5196      block = (MD_BLOCK*) md_push_block_bytes(ctx, sizeof(MD_BLOCK));
  5197      if(block == NULL)
  5198          return -1;
  5199
  5200      switch(line->type) {
  5201          case MD_LINE_HR:
  5202              block->type = MD_BLOCK_HR;
  5203              break;
  5204
  5205          case MD_LINE_ATXHEADER:
  5206          case MD_LINE_SETEXTHEADER:
  5207              block->type = MD_BLOCK_H;
  5208              break;
  5209
  5210          case MD_LINE_FENCEDCODE:
  5211          case MD_LINE_INDENTEDCODE:
  5212              block->type = MD_BLOCK_CODE;
  5213              break;
  5214
  5215          case MD_LINE_TEXT:
  5216              block->type = MD_BLOCK_P;
  5217              break;
  5218
  5219          case MD_LINE_HTML:
  5220              block->type = MD_BLOCK_HTML;
  5221              break;
  5222
  5223          case MD_LINE_BLANK:
  5224          case MD_LINE_SETEXTUNDERLINE:
  5225          case MD_LINE_TABLEUNDERLINE:
  5226          default:
  5227              MD_UNREACHABLE();
  5228              break;
  5229      }
  5230
  5231      block->flags = 0;
  5232      block->data = line->data;
  5233      block->n_lines = 0;
  5234
  5235      ctx->current_block = block;
