  5921  static int
  5922  md_is_container_mark(MD_CTX* ctx, unsigned indent, OFF beg, OFF* p_end, MD_CONTAINER* p_container)
  5923  {
  5924      OFF off = beg;
  5925      OFF max_end;
  5926
  5927      if(off >= ctx->size  ||  indent >= ctx->code_indent_offset)
  5928          return FALSE;
  5929
  5930      /* Check for block quote mark. */
  5931      if(CH(off) == _T('>')) {
  5932          off++;
  5933          p_container->ch = _T('>');
  5934          p_container->is_loose = FALSE;
  5935          p_container->is_task = FALSE;
  5936          p_container->mark_indent = indent;
  5937          p_container->contents_indent = indent + 1;
  5938          *p_end = off;
  5939          return TRUE;
  5940      }
  5941
  5942      /* Check for list item bullet mark. */
  5943      if(ISANYOF(off, _T("-+*"))  &&  (off+1 >= ctx->size || ISBLANK(off+1) || ISNEWLINE(off+1))) {
  5944          p_container->ch = CH(off);
  5945          p_container->is_loose = FALSE;
  5946          p_container->is_task = FALSE;
  5947          p_container->mark_indent = indent;
  5948          p_container->contents_indent = indent + 1;
  5949          *p_end = off+1;
  5950          return TRUE;
  5951      }
  5952
  5953      /* Check for ordered list item marks. */
  5954      max_end = off + 9;
  5955      if(max_end > ctx->size)
  5956          max_end = ctx->size;
  5957      p_container->start = 0;
  5958      while(off < max_end  &&  ISDIGIT(off)) {
  5959          p_container->start = p_container->start * 10 + CH(off) - _T('0');
  5960          off++;
  5961      }
  5962      if(off > beg  &&
  5963         off < ctx->size  &&
  5964         (CH(off) == _T('.') || CH(off) == _T(')'))  &&
  5965         (off+1 >= ctx->size || ISBLANK(off+1) || ISNEWLINE(off+1)))
  5966      {
  5967          p_container->ch = CH(off);
  5968          p_container->is_loose = FALSE;
  5969          p_container->is_task = FALSE;
  5970          p_container->mark_indent = indent;
  5971          p_container->contents_indent = indent + off - beg + 1;
  5972          *p_end = off+1;
  5973          return TRUE;
  5974      }
  5975
  5976      return FALSE;
  5977  }
